mapper.select:
SELECT er.id, er.exam_id AS examId, e.exam_name AS examName, er.user_id AS userId, u.username, u.real_name AS realName, er.start_time AS startTime, er.submit_time AS submitTime, er.status, er.total_score AS totalScore, er.objective_score AS objectiveScore, er.subjective_score AS subjectiveScore FROM exam_record er LEFT JOIN exam e ON er.exam_id = e.id LEFT JOIN user u ON er.user_id = u.id
AND er.exam_id = #{examId}
AND er.status = #{status}
ORDER BY er.create_time DESC
